#include <iostream>
#include <stack>
#include <string>
using namespace std;
int main(){string s; cin>>s; stack<char> st;
 for(char c: s){ if(c==40||c==91||c==123) st.push(c);
  else { if(st.empty()) { cout<<"false"; return 0; }
   char t=st.top(); st.pop();
   if((c==41&&t!=40)||(c==93&&t!=91)||(c==125&&t!=123)){ cout<<"false"; return 0; } } }
 cout<<(st.empty()?"true":"false"); }

